                            ctx.fillStyle = `rgb(${Math.min(255, Math.round(r))}, ${Math.min(255, Math.round(g))}, ${Math.min(255, Math.round(b))})`;
                            ctx.fillRect(x, y, 1, 1);
                        }
                    }
                }
            }
        }

        // Global state
        let rotationX = 0.5;
        let rotationY = 0.5;
        let wireframe = false;
        let paused = false;
        let lastTime = performance.now();
        let frameCount = 0;
        let fps = 0;
        const depthBuffer = {};

        // Draw wireframe
        function drawWireframe(rotatedVertices, projectedVertices) {
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
            ctx.lineWidth = 1;

            // Draw edges
            const edges = [
                [0, 1], [1, 2], [2, 3], [3, 0],
                [4, 5], [5, 6], [6, 7], [7, 4],
                [0, 4], [1, 5], [2, 6], [3, 7]
            ];

            ctx.beginPath();
            for (const [i, j] of edges) {
                ctx.moveTo(projectedVertices[i].x, projectedVertices[i].y);
                ctx.lineTo(projectedVertices[j].x, projectedVertices[j].y);
            }
            ctx.stroke();
        }

        // Main render loop
        function render() {
            // Clear canvas with fade effect
            ctx.fillStyle = 'rgba(22, 33, 62, 0.3)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            depthBuffer.clear();

            const t = performance.now() / 1000;

            // Update rotation
            if (!paused) {
                rotationX += 0.01;
                rotationY += 0.015;
            }

            // Moving light source (orbiting)
            const lightAngle = t * 0.7;
            const lightX = Math.cos(lightAngle) * 3;
            const lightY = Math.sin(lightAngle * 0.7) * 2;
            const lightZ = Math.sin(lightAngle) * 3;
            const lightDir = { x: lightX, y: lightY, z: lightZ };

            // Build rotation matrix
            const rotX = rotateX(rotationX);
            const rotY = rotateY(rotationY);
            const rotZ = rotateZ(rotationX * 0.5);
            const rotation = multiplyMatrix(multiplyMatrix(rotX, rotY), rotZ);

            // Transform vertices
            const rotatedVertices = vertices.map(v => rotatePoint(v, rotation));

            // Project vertices
            const projectedVertices = rotatedVertices.map(v => project(v, 300, 5));

            // Render faces
            for (const face of faces) {
                const indices = face.indices;
                const p0 = projectedVertices[indices[0]];
                const p1 = projectedVertices[indices[1]];
                const p2 = projectedVertices[indices[2]];

                if (!p0.visible || !p1.visible || !p2.visible) continue;

                // Calculate face normal
                const v0 = { x: p1.x - p0.x, y: p1.y - p0.y, z: p1.z - p0.z };
                const v1 = { x: p2.x - p0.x, y: p2.y - p0.y, z: p2.z - p0.z };
                const normal = { x: v0.y * v1.z - v0.z * v1.y, y: v0.z * v1.x - v0.x * v1.z, z: v0.x * v1.y - v0.y * v1.x };

                // Per-vertex lighting
                const c0 = lambertLight({ r: 30, g: 30, b: 30 }, face.color, lightDir, { x: rotatedVertices[indices[0]].x, y: rotatedVertices[indices[0]].y, z: rotatedVertices[indices[0]].z });
                const c1 = lambertLight({ r: 30, g: 30, b: 30 }, face.color, lightDir, { x: rotatedVertices[indices[1]].x, y: rotatedVertices[indices[1]].y, z: rotatedVertices[indices[1]].z });
                const c2 = lambertLight({ r: 30, g: 30, b: 30 }, face.color, lightDir, { x: rotatedVertices[indices[2]].x, y: rotatedVertices[indices[2]].y, z: rotatedVertices[indices[2]].z });

                // Rasterize with Gouraud shading
                rasterizeTriangle(p0, p1, p2, c0, c1, c2);
            }

            // Draw wireframe overlay
            if (wireframe) {
                drawWireframe(rotatedVertices, projectedVertices);
            }

            // Draw light source indicator
            const lightProject = project({ x: lightX, y: lightY, z: lightZ }, 300, 5);
            if (lightProject.visible) {
                const lightX2D = canvas.width / 2 + lightProject.x;
                const lightY2D = canvas.height / 2 + lightProject.y;
                ctx.beginPath();
                ctx.arc(lightX2D, lightY2D, 8, 0, Math.PI * 2);
                ctx.fillStyle = 'rgba(255, 255, 200, 0.8)';
                ctx.fill();
                ctx.strokeStyle = 'rgba(255, 200, 100, 0.5)';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            // FPS counter
            frameCount++;
            const now = performance.now();
            if (now - lastTime >= 1000) {
                fps = frameCount;
                frameCount = 0;
                lastTime = now;
                fpsElement.textContent = `FPS: ${fps}`;
            }

            requestAnimationFrame(render);
        }

        // Keyboard controls
        document.addEventListener('keydown', (e) => {
            if (e.key === 'W' || e.key === 'w') {
                wireframe = !wireframe;
            }
            if (e.key === 'P' || e.key === 'p') {
                paused = !paused;
            }
        });

        // Start animation
        render();
    </script>
</body>
